ics{grid-template-columns:repeat(3,1fr)}}@media(max-width:650px){.intro-panel{padding:1.8rem;border-radius:20px}.intro-copy h2{font-size:1.7rem}.scope-strip{display:block}.scope-strip strong,.scope-strip span{display:block;margin:.65rem 0 0;padding:0;border:0}.result-heading,.data-toolbar,.toolbar-actions{display:block}.toolbar-actions{margin-top:1rem}.search-box{min-width:0;margin-bottom:.6rem}.result-metrics{grid-template-columns:repeat(2,1fr)}.check-table th,.check-table td{padding:.75rem}.check-table th:nth-child(3),.check-table td:nth-child(3){display:none}}
