@section('js')
<script>
document.addEventListener('DOMContentLoaded', function () {
    var endpoint = @json(route('admin.moodle-sync.smart-check.users'));
    var testEndpoint = @json(route('admin.moodle-sync.test'));
    var resolveEndpoint = @json(route('admin.moodle-sync.smart-check.resolve-conflict'));
    var latestChecks = @json($latestChecks ?? ['students' => null, 'gtk' => null]);
    var csrf = document.querySelector('meta[name="csrf-token"]').content;
    var records = [];
    var activeSubject = 'students';
    var activeFilter = 'all';
    var search = '';
    var post = function (url, body) { var options={method:'POST', headers:{'Accept':'application/json','X-CSRF-TOKEN':csrf}}; if(body){options.headers['Content-Type']='application/json';options.body=JSON.stringify(body);} return fetch(url, options).then(function(response){return response.json().then(function(data){if(!response.ok)throw new Error(data.message || 'Permintaan gagal.');return data;});}); };
    var escapeHtml = function(value){var node=document.createElement('div');node.textContent=value || '';return node.innerHTML;};
    var label = function(status){return {missing:'Belum ada Moodle',matched:'Data sesuai',matched_variant:'Nama setara',name_different:'Nama berbeda',conflict_nisn:'Konflik NISN / identitas',without_nisn:'Tanpa NISN',without_nik:'Tanpa NIK',resolved:'Sudah diverifikasi'}[status] || status;};
    var render = function(){var body=document.getElementById('records-body');var visible=records.filter(function(item){var matchStatus=activeFilter==='all'||item.status===activeFilter;var haystack=[item.nisn,item.nik,item.nama_lengkap,item.rombel,item.jenis_ptk,item.moodle_name].join(' ').toLowerCase();return matchStatus&&haystack.indexOf(search)>=0;});document.getElementById('visible-count').textContent=visible.length.toLocaleString('id-ID')+' data';body.innerHTML=visible.map(function(item){var identifier=activeSubject==='gtk'?item.nik:item.nisn;var group=activeSubject==='gtk'?item.jenis_ptk:item.rombel;var action=item.status==='conflict_nisn'?'<button type="button" class="conflict-action" data-local-id="'+escapeHtml(item.id)+'"><i class="fas fa-shield-halved"></i> Tangani</button>':'';return '<tr><td><span class="student-name">'+escapeHtml(item.nama_lengkap)+'</span><span class="student-id">SIMANSA</span></td><td><code>'+escapeHtml(identifier || '-')+'</code></td><td>'+escapeHtml(group || '-')+'</td><td>'+escapeHtml(item.moodle_name || '-')+'</td><td><span class="status-badge status-'+item.status+'">'+label(item.status)+'</span></td><td>'+action+'</td></tr>';}).join('') || '<tr><td colspan="6" class="text-center text-muted py-4">Tidak ada data pada filter ini.</td></tr>';};
    var openLoading = function(){if(window.Swal)window.Swal.fire({title:'Smart Check sedang berjalan',html:'<div class="loading-dialog"><div class="loading-ring"></div><p>Membaca siswa aktif ber-rombel dari SIMANSA<br>dan mencocokkannya dengan Moodle.</p></div>',allowOutsideClick:false,showConfirmButton:false});};
    var applyData = function(data){records=data.records || [];document.getElementById('total-count').textContent=(data.summary.total||0).toLocaleString('id-ID');document.getElementById('missing-count').textContent=(data.summary.missing||0).toLocaleString('id-ID');document.getElementById('matched-count').textContent=(data.summary.matched||0).toLocaleString('id-ID');document.getElementById('different-count').textContent=(data.summary.conflict_nisn||data.summary.name_different||0).toLocaleString('id-ID');document.getElementById('no-id-count').textContent=(data.summary[activeSubject==='gtk'?'without_nik':'without_nisn']||0).toLocaleString('id-ID');document.getElementById('checked-at').textContent='Pemeriksaan selesai '+data.checked_at+'. Tidak ada data Moodle yang diubah.';document.getElementById('empty-state').classList.add('d-none');document.getElementById('results').classList.remove('d-none');render();};
    var run = function(){openLoading();post(endpoint,{subject:activeSubject}).then(function(data){applyData(data);if(window.Swal)window.Swal.close();if(window.toastr)window.toastr.success(data.message);}).catch(function(error){if(window.Swal)window.Swal.fire({icon:'error',title:'Smart Check gagal',text:error.message});});};
    var resolve = function(localId){var item=records.find(function(row){return String(row.id)===String(localId);});if(!item||!window.Swal)return;var identifier=activeSubject==='gtk'?item.nik:item.nisn;var identifierLabel=activeSubject==='gtk'?'NIK SIMANSA':'NISN SIMANSA';var moodleIdentifier=item.moodle_username||identifier;window.Swal.fire({title:'Tangani konflik identitas',html:'<div class="conflict-summary"><div><small>Nama SIMANSA</small><strong>'+escapeHtml(item.nama_lengkap||'-')+'</strong></div><div><small>Nama di Moodle</small><strong class="danger-text">'+escapeHtml(item.moodle_name||'-')+'</strong></div><div><small>'+identifierLabel+'</small><strong>'+escapeHtml(identifier||'-')+'</strong></div><div><small>Username Moodle saat ini</small><strong class="danger-text">'+escapeHtml(moodleIdentifier||'-')+'</strong></div></div><p class="conflict-help"><i class="fas fa-triangle-exclamation"></i><span><b>PERHATIAN:</b> Pilihan di bawah dapat mengubah identitas akun Moodle. Pastikan akun ini benar-benar milik orang yang sama. Nilai tetap mengikuti userid Moodle yang sama.</span></p><div class="resolution-options"><label><input type="radio" name="conflict-resolution" value="correct_username" checked><span><b>GANTI username/NISN Moodle</b><small>NISN Moodle lama diganti menjadi NISN baru. Nama Moodle tidak diubah.</small></span></label><label><input type="radio" name="conflict-resolution" value="update_name"><span><b>SAMAKAN nama lengkap Moodle</b><small>Nama Moodle diganti sesuai nama SIMANSA. Username/NISN Moodle tidak diubah.</small></span></label><label><input type="radio" name="conflict-resolution" value="verified"><span><b>Tandai sudah diverifikasi</b><small>Tidak melakukan perubahan apa pun ke Moodle.</small></span></label><label><input type="radio" name="conflict-resolution" value="ignored"><span><b>Lewati konflik</b><small>Tidak melakukan perubahan dan simpan untuk ditangani nanti.</small></span></label></div><div class="resolution-fields"><input id="conflict-new-username" class="swal2-input" placeholder="NISN baru akun Moodle"><small class="field-help">Isi hanya jika memilih ganti username/NISN.</small><input id="conflict-note" class="swal2-input" placeholder="Catatan admin (opsional)"></div>',customClass:{popup:'conflict-swal'},showCancelButton:true,confirmButtonText:'Lanjutkan',cancelButtonText:'Batal',focusConfirm:false,didOpen:function(){var toggle=function(){var selected=document.querySelector('input[name="conflict-resolution"]:checked').value;document.getElementById('conflict-new-username').disabled=selected!=='correct_username';};document.querySelectorAll('input[name="conflict-resolution"]').forEach(function(radio){radio.addEventListener('change',toggle);});toggle();},preConfirm:function(){var resolution=document.querySelector('input[name="conflict-resolution"]:checked').value;var newUsername=document.getElementById('conflict-new-username').value;if(resolution==='correct_username'&&!newUsername.trim()){window.Swal.showValidationMessage('NISN baru wajib diisi untuk koreksi.');return false;}return {resolution:resolution,new_username:newUsername,note:document.getElementById('conflict-note').value};}}).then(function(result){if(!result.isConfirmed)return;var value=result.value;var submit=function(){post(resolveEndpoint,{subject:activeSubject,local_id:String(localId),resolution:value.resolution,new_username:value.new_username,note:value.note}).then(function(data){if(window.toastr)window.toastr.success(data.message);run();}).catch(function(error){window.Swal.fire({icon:'error',title:'Resolusi gagal',text:error.message});});};if(value.resolution==='correct_username'){window.Swal.fire({icon:'warning',title:'Konfirmasi penggantian NISN',html:'<p>Username Moodle akan diganti:</p><p class="confirm-change"><b>'+escapeHtml(moodleIdentifier)+'</b><i class="fas fa-arrow-right"></i><b>'+escapeHtml(value.new_username)+'</b></p><p class="text-muted">Nama tidak diubah. Data nilai tetap berada pada userid yang sama.</p>',showCancelButton:true,confirmButtonText:'Ya, ganti username/NISN',cancelButtonText:'Batal'}).then(function(confirm){if(confirm.isConfirmed)submit();});}else if(value.resolution==='update_name'){window.Swal.fire({icon:'warning',title:'Konfirmasi penyamaan nama',html:'<p>Nama Moodle akan diganti:</p><p class="confirm-change"><b>'+escapeHtml(item.moodle_name||'-')+'</b><i class="fas fa-arrow-right"></i><b>'+escapeHtml(item.nama_lengkap||'-')+'</b></p><p class="text-muted">Username/NISN tidak diubah. Data nilai tetap berada pada userid yang sama.</p>',showCancelButton:true,confirmButtonText:'Ya, samakan nama',cancelButtonText:'Batal'}).then(function(confirm){if(confirm.isConfirmed)submit();});}else{submit();}});};
    var updateSubjectUi = function(){var gtk=activeSubject==='gtk';document.getElementById('records-title').textContent=gtk?'Daftar GTK':'Daftar siswa';document.getElementById('local-heading').textContent=gtk?'GTK SIMANSA':'Siswa SIMANSA';document.getElementById('identifier-heading').textContent=gtk?'NIK':'NISN';document.getElementById('group-heading').textContent=gtk?'Jenis GTK':'Rombel';document.getElementById('search-records').placeholder=gtk?'Cari NIK, nama, atau jenis GTK':'Cari NISN, nama, atau rombel';var filter=document.getElementById('status-filter');if(!filter.querySelector('option[value="conflict_nisn"]')){var option=document.createElement('option');option.value='conflict_nisn';option.textContent='Konflik identitas';filter.appendChild(option);}};
    document.querySelectorAll('.check-tab').forEach(function(tab){tab.addEventListener('click',function(){activeSubject=tab.dataset.subject;activeFilter='all';search='';document.getElementById('search-records').value='';document.getElementById('status-filter').value='all';document.querySelectorAll('.check-tab').forEach(function(item){item.classList.toggle('active',item===tab);});updateSubjectUi();if(latestChecks[activeSubject])applyData(latestChecks[activeSubject]);else{records=[];document.getElementById('results').classList.add('d-none');document.getElementById('empty-state').classList.remove('d-none');}});});
    document.getElementById('records-body').addEventListener('click',function(event){var button=event.target.closest('.conflict-action');if(button)resolve(button.dataset.localId);});
    document.getElementById('run-smart-check').addEventListener('click',run);document.getElementById('check-again').addEventListener('click',run);document.querySelectorAll('.metric-card').forEach(function(button){button.addEventListener('click',function(){activeFilter=button.dataset.filter;document.querySelectorAll('.metric-card').forEach(function(item){item.classList.remove('active');});button.classList.add('active');document.getElementById('status-filter').value=activeFilter;render();});});document.getElementById('status-filter').addEventListener('change',function(){activeFilter=this.value;document.querySelectorAll('.metric-card').forEach(function(item){item.classList.toggle('active',item.dataset.filter===activeFilter);});render();});document.getElementById('search-records').addEventListener('input',function(){search=this.value.toLowerCase();render();});document.getElementById('test-connection').addEventListener('click',function(){post(testEndpoint).then(function(data){if(window.toastr)window.toastr.success(data.message);}).catch(function(error){if(window.toastr)window.toastr.error(error.message);});});
    updateSubjectUi();if(latestChecks.students)applyData(latestChecks.students);
});
</script>
@endsection
